#Function to find schools that were dropped during scraping [I did fully write this]
find_missing <- function(df, source_df){ 
  ref_tbl <- {{ source_df }} |> 
    group_by(short_name) |> 
    summarise()
  
  summarised_df <- {{ df }} |> 
    group_by(short_name) |> 
    summarise()
  
  missing <- anti_join(ref_tbl, summarised_df)
  print(missing)
}

