      MLAX = str_detect(title, "(?<![Ww]omen's\\s)[Ll]acrosse|Men's Lacrosse|MLAX|M Lacrosse|\\sLAX"),
      MSOC = str_detect(title, "(?<![Ww]omen's\\s)[Ss]occer|Men's Soccer|MSOC|\\sSOC|SCCR"),
      MTEN = str_detect(title, "(?<![Ww]omen's\\s)[Tt]ennis|Men's Tennis|MTEN|\\sTEN"),
      MVB = str_detect(title, "Men's Volleyball|MVB|M Volleyball|\\sVB"),
      PIST = str_detect(title, "Pistol"),
      POLO = str_detect(title, "Polo"),
      RDO = str_detect(title, "Rodeo"),
      RIFL = str_detect(title, "Rifle|RIFLE"),
      ROW = str_detect(title, "Rowing|ROW"),
      RUG = str_detect(title, "Rugby"),
      SAIL = str_detect(title, "Sailing|SAIL"),
      SB = str_detect(title, "Softball|SB|SBALL"),
      SKI = str_detect(title, "Skiing|SKI"),
      SPSB = str_detect(title, "Soft Pitch Softball|SPSB"),
      SQSH = str_detect(title, "Squash"),
      SWIM = str_detect(title, "SWIM|[Ss]wimming [&] [Dd]iving|[Ss]wim [&] [Dd]ive|\\sSD|S/D"),
      TRACK = str_detect(title, "[Tt]rack [&] [Ff]ield|T[&]F|TRACK|\\sMT|\\sWT"),
      TRI = str_detect(title, "Triathalon"),
      VB = str_detect(title, "(?<!Men's\\s|Women's\\s|M\\s|W\\s)(Volleyball|VB)"), # Prevent overlap
      WBB = str_detect(title, "(?<![Mm]en's\\s)[Bb]asketball|Women's Basketball|WBB|W Basketball"),
      WGOLF = str_detect(title, "Women's Golf|WGOLF|W Golf"),                        # Fixed Men's typo
      WLAX = str_detect(title, "(?<![Mm]en's\\s)[Ll]acrosse|Women's Lacrosse|WLAX|W Lacrosse|\\sLAX"),
      WP = str_detect(title, "Water Polo|WP"),
      WREST = str_detect(title, "Wrestling|WREST"),
      WSK = str_detect(title, "Water Skiing|WS"),
      WSOC = str_detect(title, "(?<![Mm]en's\\s)[Ss]occer|Women's Soccer|WSOC|\\sSOC|SCCR"),
      WTEN = str_detect(title, "(?<![Mm]en's\\s)[Tt]ennis|Women's Tennis|WTEN|\\sTEN"),
      XC = str_detect(title, "Cross Country|XC")
    ),
    
    # 2. Return a collapsed character string row-by-row
    Sport = pmap_chr(Sport_Flags, function(...) {
      flags <- c(...)
      flags[is.na(flags)] <- FALSE
      
      # FIX 2: Since flags are now guaranteed logical, names indexing works perfectly
      matched_sports <- names(flags)[flags]
      
      if (length(matched_sports) == 0) {
        return(NA_character_)
      } else {
        return(str_c(matched_sports, collapse = ", "))
      }
    })
  ) |> 
  select(-Sport_Flags) |> 
  distinct()

# Filter Directory for SIDs and DPs or equivalent
# My contact is usually directed to the sports information director or director of photography/similar position who typically deals with and hires freelancers
final_comms_staff_directory <- comms_staff_directory |> 
  filter(
    # Keep specific high-priority creative/comms keywords regardless of coaching titles
    (str_detect(title, "(?i)\\bSID\\b|(?i)\\bAD\\b|Supervisor|Athletics? Director|Director of Athletics?|\\b(?:media|public|external)\\srelations\\b|External Operations|Photography|Head Athletics Photographer|(?<!Assistant\\s)Sports Information(?!\\sAssistant)|Director of Creative Content|Director of Creative Services|Communication| Marketing [&] Info") & 
       !str_detect(title, "(?i)Graduate Assistant|Student|Intern")) |
      
      # Otherwise, apply your standard filtering rules
      # Added 'relations' to the end of this list to filter out the ones that didn't match the top regex!
      (!is.na(Sport) & !str_detect(title, "(?i)Quart|Sports Medicine|Partnership|Learning|Photographer|Coach|Trainer|Recruiting|Designer|Advancment|Development|Engagement|Technology|relations"))
  ) |> 
  select(Name:State, short_name, staff_directory:Sport)

#Find missing schools that were filtered out
filtered_out_schools <- anti_join(comms_staff_directory, final_comms_staff_directory, by = "short_name")
filtered_out_schools <- filtered_out_schools |> 
  filter(!if_all(name:Sport, ~ .x == "NA")) |> 
  group_by(short_name) |> 
  summarise(.groups = "drop") |> 
  arrange(short_name, .locale = "en")

write_xlsx(final_comms_staff_directory, "data/ouput/filtered_contacts.xlsx")


ncaa_members_parsed <- ncaa_members_staff_parsed |> 
  select(Name:State, hostname_url, staff_directory)
write_xlsx(ncaa_members_parsed, "data/ouput/ncaa_members.xlsx")

